import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(0, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const timelines = [];
  const startPosition = new THREE.Vector3(0, 1, 0.06);
  const meshesToDispose = [];

  // Create plane geometry for card
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Load texture from assets
  const texture = ctx.textureLoader.load(config.assets.imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create TSL-compatible material
  const material = new THREE.MeshBasicNodeMaterial({
    map: texture,
    color: 0xffffff,
    transparent: true,
  });

  const plane = new THREE.Mesh(geometry, material);
  plane.position.z = 0;
  group.add(plane);

  // Render text content via fontAtlas
  let textMesh = null;
  if (config.textContent && config.textContent.length > 0) {
    const textContent = config.textContent[0];
    // Headline type scale: 0.34 scene units
    textMesh = ctx.fontAtlas.createTextMesh(textContent.text, {
      fontSize: 0.34,
      fontWeight: 400,
      fontFamily: 'Lora',
      color: 0x16161d,
      align: 'center',
      anchor: [0.5, 0.5],
    });
    textMesh.position.set(0, 0, 0.01);
    group.add(textMesh);
    meshesToDispose.push(textMesh);
  }

  // Apply cinematic primitives
  if (config.cinematicPrimitives && config.cinematicPrimitives.length > 0) {
    config.cinematicPrimitives.forEach(primitive => {
      ctx.primitives[primitive.name](group, primitive.params || {});
    });
  }

  // Setup event handlers
  let isHovering = false;
  let isFocused = false;

  group.userData.handlers = {
    mouseenter: () => {
      if (isHovering) return;
      isHovering = true;

      timelines.forEach(tl => {
        if (tl._type === 'hover') tl.kill();
      });

      const tl = gsap.timeline();
      tl._type = 'hover';
      tl.to(group.position, {
        y: startPosition.y + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      }, 0);
      timelines.push(tl);
    },
    mouseleave: () => {
      if (!isHovering) return;
      isHovering = false;

      timelines.forEach(tl => {
        if (tl._type === 'hover') tl.kill();
      });

      const tl = gsap.timeline();
      tl._type = 'hover';
      tl.to(group.position, {
        y: startPosition.y,
        duration: 0.7,
        ease: 'power3.out',
      }, 0);
      timelines.push(tl);
    },
    click: () => {
      const tl = gsap.timeline();
      tl._type = 'click';
      tl.to(group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
      }, 0);
      tl.to(group.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.12,
        ease: 'back.out',
      }, '+=0.12');
      timelines.push(tl);

      if (ctx.emit) {
        ctx.emit('hub-journal.select');
      }
    },
    focus: () => {
      if (isFocused) return;
      isFocused = true;

      const outlineGeometry = new THREE.PlaneGeometry(1.05, 1.05);
      const outlineMaterial = new THREE.MeshBasicNodeMaterial({
        color: 0xff2a38,
        transparent: true,
        opacity: 0.5,
        side: THREE.BackSide,
      });
      const outline = new THREE.Mesh(outlineGeometry, outlineMaterial);
      outline.position.z = -0.005;
      group.add(outline);

      group.userData._outline = { mesh: outline, material: outlineMaterial, geometry: outlineGeometry };
    },
    blur: () => {
      if (!isFocused) return;
      isFocused = false;

      if (group.userData._outline) {
        group.remove(group.userData._outline.mesh);
        group.userData._outline.geometry.dispose();
        group.userData._outline.material.dispose();
        delete group.userData._outline;
      }
    },
  };

  // Cleanup function
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;

    if (group.userData._outline) {
      group.userData._outline.geometry.dispose();
      group.userData._outline.material.dispose();
      delete group.userData._outline;
    }

    meshesToDispose.forEach(mesh => {
      if (mesh.geometry) mesh.geometry.dispose();
      if (mesh.material) mesh.material.dispose();
    });

    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return group;
}
